select public.upsert_bank_question($json${"id":"poet2-easy-005","type":"choice","level":"easy","testament":"ot","book":"JOB","chapter":1,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Quantos filhos e filhas tinha Jó no início da história?","bible_ref":"Jó 1:2","verse_text":"E nasceram-lhe sete filhos e três filhas."},"fr":{"prompt":"Combien de fils et de filles Job avait-il au début de l’histoire ?","bible_ref":"Job 1:2","verse_text":"Il lui naquit sept fils et trois filles."},"en":{"prompt":"How many sons and daughters did Job have at the start of the story?","bible_ref":"Job 1:2","verse_text":"And there were born unto him seven sons and three daughters."},"es":{"prompt":"¿Cuántos hijos e hijas tenía Job al principio de la historia?","bible_ref":"Job 1:2","verse_text":"Y naciéronle siete hijos y tres hijas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sete filhos e três filhas"},"fr":{"text":"Sept fils et trois filles"},"en":{"text":"Seven sons and three daughters"},"es":{"text":"Siete hijos y tres hijas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Doze filhos e uma filha"},"fr":{"text":"Douze fils et une fille"},"en":{"text":"Twelve sons and one daughter"},"es":{"text":"Doce hijos y una hija"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Três filhos e sete filhas"},"fr":{"text":"Trois fils et sept filles"},"en":{"text":"Three sons and seven daughters"},"es":{"text":"Tres hijos y siete hijas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dois filhos e duas filhas"},"fr":{"text":"Deux fils et deux filles"},"en":{"text":"Two sons and two daughters"},"es":{"text":"Dos hijos y dos hijas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-easy-006","type":"choice","level":"easy","testament":"ot","book":"JOB","chapter":1,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Depois de perder tudo, o que fez Jó?","bible_ref":"Jó 1:20","verse_text":"Então Jó se levantou, rasgou sua capa, rapou sua cabeça, e caindo na terra, adorou,"},"fr":{"prompt":"Après avoir tout perdu, que fit Job ?","bible_ref":"Job 1:20","verse_text":"Alors Job se leva, déchira son manteau, et se rasa la tête; puis, se jetant par terre, il se prosterna,"},"en":{"prompt":"After losing everything, what did Job do?","bible_ref":"Job 1:20","verse_text":"Then Job arose, and rent his mantle, and shaved his head, and fell down upon the ground, and worshipped,"},"es":{"prompt":"Después de perderlo todo, ¿qué hizo Job?","bible_ref":"Job 1:20","verse_text":"Entonces Job se levantó, y rasgó su manto, y trasquiló su cabeza, y cayendo en tierra adoró;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Prostrou-se em terra e adorou"},"fr":{"text":"Il se jeta par terre et se prosterna"},"en":{"text":"He fell down upon the ground and worshipped"},"es":{"text":"Cayó en tierra y adoró"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Fugiu para o deserto"},"fr":{"text":"Il s’enfuit au désert"},"en":{"text":"He ran away into the wilderness"},"es":{"text":"Huyó al desierto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Amaldiçoou a Deus"},"fr":{"text":"Il maudit Dieu"},"en":{"text":"He cursed God"},"es":{"text":"Maldijo a Dios"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Construiu uma casa nova"},"fr":{"text":"Il construisit une nouvelle maison"},"en":{"text":"He built a new house"},"es":{"text":"Construyó una casa nueva"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-easy-007","type":"choice","level":"easy","testament":"ot","book":"JOB","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Jó 1:1, que tipo de homem era Jó?","bible_ref":"Jó 1:1","verse_text":"Havia um homem na terra de Uz, cujo nome era Jó; e este homem era íntegro e correto, temente a Deus, e que se afastava do mal."},"fr":{"prompt":"Selon Job 1:1, quel genre d’homme était Job ?","bible_ref":"Job 1:1","verse_text":"Il y avait dans le pays d’Uts un homme qui s’appelait Job. Et cet homme était intègre et droit; il craignait Dieu, et se détournait du mal."},"en":{"prompt":"According to Job 1:1, what kind of man was Job?","bible_ref":"Job 1:1","verse_text":"There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."},"es":{"prompt":"Según Job 1:1, ¿qué clase de hombre era Job?","bible_ref":"Job 1:1","verse_text":"Hubo un varón en tierra de Hus, llamado Job; y era este hombre perfecto y recto, y temeroso de Dios, y apartado del mal."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Íntegro e correto"},"fr":{"text":"Intègre et droit"},"en":{"text":"Perfect and upright"},"es":{"text":"Perfecto y recto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Preguiçoso e tolo"},"fr":{"text":"Paresseux et insensé"},"en":{"text":"Lazy and foolish"},"es":{"text":"Perezoso y necio"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pobre e doente"},"fr":{"text":"Pauvre et malade"},"en":{"text":"Poor and sick"},"es":{"text":"Pobre y enfermo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Orgulhoso e cruel"},"fr":{"text":"Orgueilleux et cruel"},"en":{"text":"Proud and cruel"},"es":{"text":"Orgulloso y cruel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-easy-008","type":"choice","level":"easy","testament":"ot","book":"PSA","chapter":23,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"No Salmo 23, por qual vale anda o salmista sem temer mal algum?","bible_ref":"Salmos 23:4","verse_text":"Ainda que eu venha a andar pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; tua vara e teu cajado me consolam."},"fr":{"prompt":"Dans le Psaume 23, dans quelle vallée le psalmiste marche-t-il sans craindre aucun mal ?","bible_ref":"Psaumes 23:4","verse_text":"Quand je marche dans la vallée de l’ombre de la mort, Je ne crains aucun mal, car tu es avec moi: Ta houlette et ton bâton me rassurent."},"en":{"prompt":"In Psalm 23, through which valley does the psalmist walk without fearing evil?","bible_ref":"Psalms 23:4","verse_text":"Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."},"es":{"prompt":"En el Salmo 23, ¿por qué valle anda el salmista sin temer mal alguno?","bible_ref":"Salmos 23:4","verse_text":"Aunque ande en valle de sombra de muerte, no temeré mal alguno; porque tú estarás conmigo: tu vara y tu cayado me infundirán aliento."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O vale da sombra da morte"},"fr":{"text":"La vallée de l’ombre de la mort"},"en":{"text":"The valley of the shadow of death"},"es":{"text":"El valle de sombra de muerte"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O vale do Jordão"},"fr":{"text":"La vallée du Jourdain"},"en":{"text":"The valley of the Jordan"},"es":{"text":"El valle del Jordán"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O vale dos leões"},"fr":{"text":"La vallée des lions"},"en":{"text":"The valley of lions"},"es":{"text":"El valle de los leones"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O vale das flores"},"fr":{"text":"La vallée des fleurs"},"en":{"text":"The valley of flowers"},"es":{"text":"El valle de las flores"}}}]}$json$::jsonb);
