select public.upsert_bank_question($json${"id":"poet2-medium-008","type":"choice","level":"medium","testament":"ot","book":"JOB","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Em que terra vivia Jó?","bible_ref":"Jó 1:1","verse_text":"Havia um homem na terra de Uz, cujo nome era Jó; e este homem era íntegro e correto, temente a Deus, e que se afastava do mal."},"fr":{"prompt":"Dans quel pays vivait Job ?","bible_ref":"Job 1:1","verse_text":"Il y avait dans le pays d’Uts un homme qui s’appelait Job. Et cet homme était intègre et droit; il craignait Dieu, et se détournait du mal."},"en":{"prompt":"In which land did Job live?","bible_ref":"Job 1:1","verse_text":"There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."},"es":{"prompt":"¿En qué tierra vivía Job?","bible_ref":"Job 1:1","verse_text":"Hubo un varón en tierra de Hus, llamado Job; y era este hombre perfecto y recto, y temeroso de Dios, y apartado del mal."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uz"},"fr":{"text":"Uts"},"en":{"text":"Uz"},"es":{"text":"Hus"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Egipto"},"fr":{"text":"Égypte"},"en":{"text":"Egypt"},"es":{"text":"Egipto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Canaã"},"fr":{"text":"Canaan"},"en":{"text":"Canaan"},"es":{"text":"Canaán"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moabe"},"fr":{"text":"Moab"},"en":{"text":"Moab"},"es":{"text":"Moab"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-009","type":"choice","level":"medium","testament":"ot","book":"JOB","chapter":2,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Com que se raspava Jó, sentado no meio da cinza?","bible_ref":"Jó 2:8","verse_text":"E Jó tomou um caco para se raspar com ele, e ficou sentado no meio da cinza."},"fr":{"prompt":"Avec quoi Job se grattait-il, assis sur la cendre ?","bible_ref":"Job 2:8","verse_text":"Et Job prit un tesson pour se gratter et s’assit sur la cendre."},"en":{"prompt":"What did Job take to scrape himself as he sat among the ashes?","bible_ref":"Job 2:8","verse_text":"And he took him a potsherd to scrape himself withal; and he sat down among the ashes."},"es":{"prompt":"¿Con qué se rascaba Job, sentado en medio de ceniza?","bible_ref":"Job 2:8","verse_text":"Y tomaba una teja para rascarse con ella, y estaba sentado en medio de ceniza."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um caco"},"fr":{"text":"Un tesson"},"en":{"text":"A potsherd"},"es":{"text":"Una teja"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma pedra"},"fr":{"text":"Une pierre"},"en":{"text":"A stone"},"es":{"text":"Una piedra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma faca"},"fr":{"text":"Un couteau"},"en":{"text":"A knife"},"es":{"text":"Un cuchillo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um ramo"},"fr":{"text":"Une branche"},"en":{"text":"A branch"},"es":{"text":"Una rama"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-010","type":"choice","level":"medium","testament":"ot","book":"JOB","chapter":32,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Quando Eliú começou a falar, o que disse de si mesmo?","bible_ref":"Jó 32:6","verse_text":"Por isso Eliú, filho de Baraquel, buzita, respondeu, dizendo: Eu sou jovem e vós sois idosos; por isso fiquei receoso e tive medo de vos declarar minha opinião."},"fr":{"prompt":"Quand Élihu prit la parole, que dit-il de lui-même ?","bible_ref":"Job 32:6","verse_text":"Et Élihu, fils de Barakeel de Buz, prit la parole et dit: Je suis jeune, et vous êtes des vieillards; C’est pourquoi j’ai craint, j’ai redouté De vous faire connaître mon sentiment."},"en":{"prompt":"When Elihu began to speak, what did he say about himself?","bible_ref":"Job 32:6","verse_text":"And Elihu the son of Barachel the Buzite answered and said, I am young, and ye are very old; wherefore I was afraid, and durst not shew you mine opinion."},"es":{"prompt":"Cuando Eliú comenzó a hablar, ¿qué dijo de sí mismo?","bible_ref":"Job 32:6","verse_text":"Y respondió Eliú hijo de Barachêl, Bucita, y dijo: Yo soy menor de días, y vosotros viejos; he tenido por tanto miedo, y temido declararos mi opinión."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Que era jovem"},"fr":{"text":"Qu’il était jeune"},"en":{"text":"That he was young"},"es":{"text":"Que era joven"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Que era profeta"},"fr":{"text":"Qu’il était prophète"},"en":{"text":"That he was a prophet"},"es":{"text":"Que era profeta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Que era rei"},"fr":{"text":"Qu’il était roi"},"en":{"text":"That he was a king"},"es":{"text":"Que era rey"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Que era irmão de Jó"},"fr":{"text":"Qu’il était le frère de Job"},"en":{"text":"That he was Job’s brother"},"es":{"text":"Que era hermano de 