select public.upsert_bank_question($json${"id":"poet2-medium-011","type":"choice","level":"medium","testament":"ot","book":"JOB","chapter":42,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Jó 42:10, por quem orava Jó quando o SENHOR o restaurou?","bible_ref":"Jó 42:10","verse_text":"E o SENHOR livrou Jó de seu infortúnio, enquanto ele orava pelos seus amigos; e o SENHOR acrescentou a Jó o dobro de tudo quanto ele antes possuía."},"fr":{"prompt":"Selon Job 42:10, pour qui Job avait-il prié quand l’Éternel le rétablit ?","bible_ref":"Job 42:10","verse_text":"L’Éternel rétablit Job dans son premier état, quand Job eut prié pour ses amis; et l’Éternel lui accorda le double de tout ce qu’il avait possédé."},"en":{"prompt":"According to Job 42:10, for whom did Job pray when the LORD turned his captivity?","bible_ref":"Job 42:10","verse_text":"And the LORD turned the captivity of Job, when he prayed for his friends: also the LORD gave Job twice as much as he had before."},"es":{"prompt":"Según Job 42:10, ¿por quiénes oraba Job cuando Jehová mudó su aflicción?","bible_ref":"Job 42:10","verse_text":"Y mudó Jehová la aflicción de Job, orando él por sus amigos: y aumentó al doble todas las cosas que habían sido de Job."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Pelos seus amigos"},"fr":{"text":"Pour ses amis"},"en":{"text":"For his friends"},"es":{"text":"Por sus amigos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pela sua mulher"},"fr":{"text":"Pour sa femme"},"en":{"text":"For his wife"},"es":{"text":"Por su mujer"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Pelos seus filhos"},"fr":{"text":"Pour ses fils"},"en":{"text":"For his sons"},"es":{"text":"Por sus hijos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pelo rei"},"fr":{"text":"Pour le roi"},"en":{"text":"For the king"},"es":{"text":"Por el rey"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-012","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo o Salmo 1:1, o homem bem-aventurado não se senta junto de quem?","bible_ref":"Salmos 1:1","verse_text":"Bem-aventurado o homem que não anda no conselho dos maus, nem fica parado no caminho dos pecadores, nem se senta junto dos escarnecedores."},"fr":{"prompt":"Selon le Psaume 1:1, en compagnie de qui l’homme heureux ne s’assied-il pas ?","bible_ref":"Psaumes 1:1","verse_text":"Heureux l’homme qui ne marche pas selon le conseil des méchants, Qui ne s’arrête pas sur la voie des pécheurs, Et qui ne s’assied pas en compagnie des moqueurs,"},"en":{"prompt":"According to Psalm 1:1, in whose seat does the blessed man not sit?","bible_ref":"Psalms 1:1","verse_text":"Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful."},"es":{"prompt":"Según el Salmo 1:1, ¿en silla de quiénes no se sienta el varón bienaventurado?","bible_ref":"Salmos 1:1","verse_text":"Bienaventurado el varón que no anduvo en consejo de malos, ni estuvo en camino de pecadores, ni en silla de escarnecedores se ha sentado;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dos escarnecedores"},"fr":{"text":"Des moqueurs"},"en":{"text":"The scornful"},"es":{"text":"De escarnecedores"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dos sábios"},"fr":{"text":"Des sages"},"en":{"text":"The wise"},"es":{"text":"De sabios"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dos pobres"},"fr":{"text":"Des pauvres"},"en":{"text":"The poor"},"es":{"text":"De pobres"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dos sacerdotes"},"fr":{"text":"Des prêtres"},"en":{"text":"The priests"},"es":{"text":"De sacerdotes"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-013","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":37,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo o Salmo 37:4, o que dará o SENHOR a quem se agrada nele?","bible_ref":"Salmos 37:4","verse_text":"E agrada-te no SENHOR; e ele te dará os pedidos de teu coração."},"fr":{"prompt":"Selon le Psaume 37:4, que donnera l’Éternel à celui qui fait de lui ses délices ?","bible_ref":"Psaumes 37:4","verse_text":"Fais de l’Éternel tes délices, Et il te donnera ce que ton cœur désire."},"en":{"prompt":"According to Psalm 37:4, what will the LORD give to the one who delights in him?","bible_ref":"Psalms 37:4","verse_text":"Delight thyself also in the LORD; and he shall give thee the desires of thine heart."},"es":{"prompt":"Según el Salmo 37:4, ¿qué dará Jehová al que pone en él su delicia?","bible_ref":"Salmos 37:4","verse_text":"Pon asimismo tu delicia en Jehová, y él te dará las peticiones de tu corazón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os pedidos do seu coração"},"fr":{"text":"Ce que son cœur désire"},"en":{"text":"The desires of his heart"},"es":{"text":"Las peticiones de su corazón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Muitas riquezas"},"fr":{"text":"De grandes richesses"},"en":{"text":"Great riches"},"es":{"text":"Muchas riquezas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um reino na terra"},"fr":{"text":"Un royaume sur la terre"},"en":{"text":"A kingdom on earth"},"es":{"text":"Un reino en la tierra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fama entre os povos"},"fr":{"text":"La renommée parmi les peuples"},"en":{"text":"Fame among the nations"},"es":{"text":"Fama entre los pueblos"}}}]}$json$::jsonb);
