select public.upsert_bank_question($json${"id":"poet2-medium-015","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":90,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo o Salmo 90:4, aos olhos de Deus, mil anos são como quê?","bible_ref":"Salmos 90:4","verse_text":"Porque mil anos aos teus olhos são como o dia de ontem, que passou, e como a vigília da noite."},"fr":{"prompt":"Selon le Psaume 90:4, à quoi sont semblables mille ans aux yeux de Dieu ?","bible_ref":"Psaumes 90:4","verse_text":"Car mille ans sont, à tes yeux, Comme le jour d’hier, quand il n’est plus, Et comme une veille de la nuit."},"en":{"prompt":"According to Psalm 90:4, a thousand years in God’s sight are like what?","bible_ref":"Psalms 90:4","verse_text":"For a thousand years in thy sight are but as yesterday when it is past, and as a watch in the night."},"es":{"prompt":"Según el Salmo 90:4, ¿a qué son semejantes mil años delante de los ojos de Dios?","bible_ref":"Salmos 90:4","verse_text":"Porque mil años delante de tus ojos, son como el día de ayer, que pasó, y como una de las vigilias de la noche."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O dia de ontem, que passou"},"fr":{"text":"Le jour d’hier, quand il n’est plus"},"en":{"text":"Yesterday when it is past"},"es":{"text":"El día de ayer, que pasó"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um século"},"fr":{"text":"Un siècle"},"en":{"text":"A century"},"es":{"text":"Un siglo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma eternidade"},"fr":{"text":"Une éternité"},"en":{"text":"An eternity"},"es":{"text":"Una eternidad"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um ano inteiro"},"fr":{"text":"Une année entière"},"en":{"text":"A whole year"},"es":{"text":"Un año entero"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-016","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":103,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo o Salmo 103:12, tão longe como o oriente está do ocidente, o que afastou Deus de nós?","bible_ref":"Salmos 103:12","verse_text":"Assim como o oriente está longe do ocidente, assim também ele tira para longe de nós nossas transgressões."},"fr":{"prompt":"Selon le Psaume 103:12, autant l’orient est éloigné de l’occident, qu’est-ce que Dieu éloigne de nous ?","bible_ref":"Psaumes 103:12","verse_text":"Autant l’orient est éloigné de l’occident, Autant il éloigne de nous nos transgressions."},"en":{"prompt":"According to Psalm 103:12, as far as the east is from the west, what has God removed from us?","bible_ref":"Psalms 103:12","verse_text":"As far as the east is from the west, so far hath he removed our transgressions from us."},"es":{"prompt":"Según el Salmo 103:12, cuanto está lejos el oriente del occidente, ¿qué alejó Dios de nosotros?","bible_ref":"Salmos 103:12","verse_text":"Cuanto está lejos el oriente del occidente, hizo alejar de nosotros nuestras rebeliones."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"As nossas transgressões"},"fr":{"text":"Nos transgressions"},"en":{"text":"Our transgressions"},"es":{"text":"Nuestras rebeliones"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os nossos inimigos"},"fr":{"text":"Nos ennemis"},"en":{"text":"Our enemies"},"es":{"text":"Nuestros enemigos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As nossas riquezas"},"fr":{"text":"Nos richesses"},"en":{"text":"Our riches"},"es":{"text":"Nuestras riquezas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os nossos amigos"},"fr":{"text":"Nos amis"},"en":{"text":"Our friends"},"es":{"text":"Nuestros amigos"}}}]}$json$::jsonb);
