select public.upsert_bank_question($json${"id":"poet2-medium-018","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":119,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Segundo o Salmo 119:11, onde guardou o salmista a palavra de Deus, para não pecar?","bible_ref":"Salmos 119:11","verse_text":"Guardei a tua palavra em meu coração, para eu não pecar contra ti."},"fr":{"prompt":"Selon le Psaume 119:11, où le psalmiste serre-t-il la parole de Dieu, afin de ne pas pécher ?","bible_ref":"Psaumes 119:11","verse_text":"Je serre ta parole dans mon cœur, Afin de ne pas pécher contre toi."},"en":{"prompt":"According to Psalm 119:11, where did the psalmist hide God’s word, that he might not sin?","bible_ref":"Psalms 119:11","verse_text":"Thy word have I hid in mine heart, that I might not sin against thee."},"es":{"prompt":"Según el Salmo 119:11, ¿dónde guardó el salmista los dichos de Dios para no pecar?","bible_ref":"Salmos 119:11","verse_text":"En mi corazón he guardado tus dichos, para no pecar contra ti."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No seu coração"},"fr":{"text":"Dans son cœur"},"en":{"text":"In his heart"},"es":{"text":"En su corazón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Num livro"},"fr":{"text":"Dans un livre"},"en":{"text":"In a book"},"es":{"text":"En un libro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Na arca"},"fr":{"text":"Dans l’arche"},"en":{"text":"In the ark"},"es":{"text":"En el arca"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No templo"},"fr":{"text":"Dans le temple"},"en":{"text":"In the temple"},"es":{"text":"En el templo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-019","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":133,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo o Salmo 133:1, para quem é bom e agradável viver em união?","bible_ref":"Salmos 133:1","verse_text":"Cântico dos degraus, de Davi: Vede como é bom e agradável que irmãos convivam em união!"},"fr":{"prompt":"Selon le Psaume 133:1, pour qui est-il agréable et doux de demeurer ensemble ?","bible_ref":"Psaumes 133:1","verse_text":"Cantique des degrés. De David. Voici, oh! Qu’il est agréable, qu’il est doux Pour des frères de demeurer ensemble!"},"en":{"prompt":"According to Psalm 133:1, for whom is it good and pleasant to dwell together in unity?","bible_ref":"Psalms 133:1","verse_text":"A Song of degrees of David. Behold, how good and how pleasant it is for brethren to dwell together in unity!"},"es":{"prompt":"Según el Salmo 133:1, ¿para quiénes es bueno y delicioso habitar juntos en uno?","bible_ref":"Salmos 133:1","verse_text":"Cántico gradual: de David. ¡MIRAD cuán bueno y cuán delicioso es habitar los hermanos igualmente en uno!"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os irmãos"},"fr":{"text":"Des frères"},"en":{"text":"Brethren"},"es":{"text":"Los hermanos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os reis"},"fr":{"text":"Des rois"},"en":{"text":"Kings"},"es":{"text":"Los reyes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os soldados"},"fr":{"text":"Des soldats"},"en":{"text":"Soldiers"},"es":{"text":"Los soldados"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os vizinhos"},"fr":{"text":"Des voisins"},"en":{"text":"Neighbours"},"es":{"text":"Los vecinos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-020","type":"choice","level":"medium","testament":"ot","book":"PSA","chapter":137,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo o Salmo 137:1, junto aos rios de que lugar se sentavam e choravam, lembrando-se de Sião?","bible_ref":"Salmos 137:1","verse_text":"Junto aos rios da Babilônia nos sentamos e choramos, enquanto nos lembramos de Sião."},"fr":{"prompt":"Selon le Psaume 137:1, au bord des fleuves de quel lieu étaient-ils assis à pleurer en se souvenant de Sion ?","bible_ref":"Psaumes 137:1","verse_text":"Sur les bords des fleuves de Babylone, Nous étions assis et nous pleurions, En nous souvenant de Sion."},"en":{"prompt":"According to Psalm 137:1, by the rivers of which place did they sit down and weep, remembering Zion?","bible_ref":"Psalms 137:1","verse_text":"By the rivers of Babylon, there we sat down, yea, we wept, when we remembered Zion."},"es":{"prompt":"Según el Salmo 137:1, ¿junto a los ríos de qué lugar se sentaban y lloraban, acordándose de Sión?","bible_ref":"Salmos 137:1","verse_text":"Junto á los ríos de Babilonia, allí nos sentábamos, y aun llorábamos, acordándonos de Sión."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Babilónia"},"fr":{"text":"Babylone"},"en":{"text":"Babylon"},"es":{"text":"Babilonia"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nínive"},"fr":{"text":"Ninive"},"en":{"text":"Nineveh"},"es":{"text":"Nínive"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Egipto"},"fr":{"text":"Égypte"},"en":{"text":"Egypt"},"es":{"text":"Egipto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Damasco"},"fr":{"text":"Damas"},"en":{"text":"Damascus"},"es":{"text":"Damasco"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-021","type":"choice","level":"medium","testament":"ot","book":"PRO","chapter":3,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Provérbios 3:12, a quem repreende o SENHOR?","bible_ref":"Provérbios 3:12","verse_text":"Porque o SENHOR repreende a quem ele ama, assim como o pai ao filho, a quem ele quer bem."},"fr":{"prompt":"Selon Proverbes 3:12, qui l’Éternel châtie-t-il ?","bible_ref":"Proverbes 3:12","verse_text":"Car l’Éternel châtie celui qu’il aime, Comme un père l’enfant qu’il chérit."},"en":{"prompt":"According to Proverbs 3:12, whom does the LORD correct?","bible_ref":"Proverbs 3:12","verse_text":"For whom the LORD loveth he correcteth; even as a father the son in whom he delighteth."},"es":{"prompt":"Según Proverbios 3:12, ¿a quién castiga Jehová?","bible_ref":"Proverbios 3:12","verse_text":"Porque al que ama castiga, como el padre al hijo á quien quiere."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Aquele que ama"},"fr":{"text":"Celui qu’il aime"},"en":{"text":"The one he loves"},"es":{"text":"Al que ama"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Aquele que odeia"},"fr":{"text":"Celui qu’il hait"},"en":{"text":"The one he hates"},"es":{"text":"Al que aborrece"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os estrangeiros"},"fr":{"text":"Les étrangers"},"en":{"text":"The strangers"},"es":{"text":"A los extranjeros"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os reis da terra"},"fr":{"text":"Les rois de la terre"},"en":{"text":"The kings of the earth"},"es":{"text":"A los reyes de la tierra"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-022","type":"choice","level":"medium","testament":"ot","book":"PRO","chapter":4,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"Segundo Provérbios 4:23, o que deves guardar acima de tudo?","bible_ref":"Provérbios 4:23","verse_text":"Acima de tudo o que se deve guardar, guarda o teu coração; porque dele procedem as saídas da vida."},"fr":{"prompt":"Selon Proverbes 4:23, que faut-il garder plus que toute autre chose ?","bible_ref":"Proverbes 4:23","verse_text":"Garde ton cœur plus que toute autre chose, Car de lui viennent les sources de la vie."},"en":{"prompt":"According to Proverbs 4:23, what must you keep with all diligence?","bible_ref":"Proverbs 4:23","verse_text":"Keep thy heart with all diligence; for out of it are the issues of life."},"es":{"prompt":"Según Proverbios 4:23, ¿qué debes guardar sobre toda cosa guardada?","bible_ref":"Proverbios 4:23","verse_text":"Sobre toda cosa guardada guarda tu corazón; porque de él mana la vida."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O teu coração"},"fr":{"text":"Ton cœur"},"en":{"text":"Your heart"},"es":{"text":"Tu corazón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O teu dinheiro"},"fr":{"text":"Ton argent"},"en":{"text":"Your money"},"es":{"text":"Tu dinero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A tua casa"},"fr":{"text":"Ta maison"},"en":{"text":"Your house"},"es":{"text":"Tu casa"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O teu nome"},"fr":{"text":"Ton nom"},"en":{"text":"Your name"},"es":{"text":"Tu nombre"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-023","type":"choice","level":"medium","testament":"ot","book":"PRO","chapter":12,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo Provérbios 12:4, o que é a mulher virtuosa para o seu marido?","bible_ref":"Provérbios 12:4","verse_text":"A mulher virtuosa é a coroa de seu marido; mas a causadora de vergonha é como uma podridão em seus ossos."},"fr":{"prompt":"Selon Proverbes 12:4, qu’est la femme vertueuse pour son mari ?","bible_ref":"Proverbes 12:4","verse_text":"Une femme vertueuse est la couronne de son mari, Mais celle qui fait honte est comme la carie dans ses os."},"en":{"prompt":"According to Proverbs 12:4, what is a virtuous woman to her husband?","bible_ref":"Proverbs 12:4","verse_text":"A virtuous woman is a crown to her husband: but she that maketh ashamed is as rottenness in his bones."},"es":{"prompt":"Según Proverbios 12:4, ¿qué es la mujer virtuosa para su marido?","bible_ref":"Proverbios 12:4","verse_text":"La mujer virtuosa corona es de su marido: mas la mala, como carcoma en sus huesos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A coroa"},"fr":{"text":"La couronne"},"en":{"text":"A crown"},"es":{"text":"La corona"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O escudo"},"fr":{"text":"Le bouclier"},"en":{"text":"A shield"},"es":{"text":"El escudo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O tesouro"},"fr":{"text":"Le trésor"},"en":{"text":"A treasure"},"es":{"text":"El tesoro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A lâmpada"},"fr":{"text":"La lampe"},"en":{"text":"A lamp"},"es":{"text":"La lámpara"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-024","type":"choice","level":"medium","testament":"ot","book":"PRO","chapter":18,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Provérbios 18:10, o que é o nome do SENHOR?","bible_ref":"Provérbios 18:10","verse_text":"O nome do SENHOR é uma torre forte; o justo correrá até ele, e ficará seguro."},"fr":{"prompt":"Selon Proverbes 18:10, qu’est le nom de l’Éternel ?","bible_ref":"Proverbes 18:10","verse_text":"Le nom de l’Éternel est une tour forte; Le juste s’y réfugie, et se trouve en sûreté."},"en":{"prompt":"According to Proverbs 18:10, what is the name of the LORD?","bible_ref":"Proverbs 18:10","verse_text":"The name of the LORD is a strong tower: the righteous runneth into it, and is safe."},"es":{"prompt":"Según Proverbios 18:10, ¿qué es el nombre de Jehová?","bible_ref":"Proverbios 18:10","verse_text":"Torre fuerte es el nombre de Jehová: á él correrá el justo, y será levantado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma torre forte"},"fr":{"text":"Une tour forte"},"en":{"text":"A strong tower"},"es":{"text":"Una torre fuerte"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma espada afiada"},"fr":{"text":"Une épée tranchante"},"en":{"text":"A sharp sword"},"es":{"text":"Una espada aguda"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um rio profundo"},"fr":{"text":"Un fleuve profond"},"en":{"text":"A deep river"},"es":{"text":"Un río profundo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma lâmpada acesa"},"fr":{"text":"Une lampe allumée"},"en":{"text":"A burning lamp"},"es":{"text":"Una lámpara encendida"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-025","type":"choice","level":"medium","testament":"ot","book":"PRO","chapter":25,"verse_start":21,"verse_end":22,"texts":{"pt":{"prompt":"Segundo Provérbios 25:21-22, se deres pão ao teu inimigo com fome, o que amontoarás sobre a cabeça dele?","bible_ref":"Provérbios 25:21-22","verse_text":"Se aquele que te odeia tiver fome, dá-lhe pão para comer; e se tiver sede, dá-lhe água para beber; Porque assim amontoarás brasas sobre a cabeça dele, e o SENHOR te recompensará."},"fr":{"prompt":"Selon Proverbes 25:21-22, si tu donnes du pain à ton ennemi qui a faim, qu’amasses-tu sur sa tête ?","bible_ref":"Proverbes 25:21-22","verse_text":"Si ton ennemi a faim, donne-lui du pain à manger; S’il a soif, donne-lui de l’eau à boire. Car ce sont des charbons ardents que tu amasses sur sa tête, Et l’Éternel te récompensera."},"en":{"prompt":"According to Proverbs 25:21-22, if you give bread to your hungry enemy, what do you heap upon his head?","bible_ref":"Proverbs 25:21-22","verse_text":"If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink: For thou shalt heap coals of fire upon his head, and the LORD shall reward thee."},"es":{"prompt":"Según Proverbios 25:21-22, si das pan al que te aborrece cuando tiene hambre, ¿qué allegas sobre su cabeza?","bible_ref":"Proverbios 25:21-22","verse_text":"Si el que te aborrece tuviere hambre, dale de comer pan; y si tuviere sed, dale de beber agua: Porque ascuas allegas sobre su cabeza, y Jehová te lo pagará."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Brasas"},"fr":{"text":"Des charbons ardents"},"en":{"text":"Coals of fire"},"es":{"text":"Ascuas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pó"},"fr":{"text":"De la poussière"},"en":{"text":"Dust"},"es":{"text":"Polvo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cinza"},"fr":{"text":"De la cendre"},"en":{"text":"Ashes"},"es":{"text":"Ceniza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Azeite"},"fr":{"text":"De l’huile"},"en":{"text":"Oil"},"es":{"text":"Aceite"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-026","type":"choice","level":"medium","testament":"ot","book":"ECC","chapter":4,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Eclesiastes 4:12, que cordão não se rompe depressa?","bible_ref":"Eclesiastes 4:12","verse_text":"E se alguém prevalecer contra um, dois podem resistir contra ele; porque o cordão de três dobras não se rompe tão depressa."},"fr":{"prompt":"Selon l’Ecclésiaste 4:12, quelle corde ne se rompt pas facilement ?","bible_ref":"Ecclésiaste 4:12","verse_text":"Et si quelqu’un est plus fort qu’un seul, les deux peuvent lui résister; et la corde à trois fils ne se rompt pas facilement."},"en":{"prompt":"According to Ecclesiastes 4:12, which cord is not quickly broken?","bible_ref":"Ecclesiastes 4:12","verse_text":"And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken."},"es":{"prompt":"Según Eclesiastés 4:12, ¿qué cordón no se rompe pronto?","bible_ref":"Eclesiastés 4:12","verse_text":"Y si alguno prevaleciere contra el uno, dos estarán contra él; y cordón de tres dobleces no presto se rompe."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O de três dobras"},"fr":{"text":"La corde à trois fils"},"en":{"text":"A threefold cord"},"es":{"text":"El de tres dobleces"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O de ouro"},"fr":{"text":"La corde d’or"},"en":{"text":"A golden cord"},"es":{"text":"El de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O de duas dobras"},"fr":{"text":"La corde à deux fils"},"en":{"text":"A twofold cord"},"es":{"text":"El de dos dobleces"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O de linho"},"fr":{"text":"La corde de lin"},"en":{"text":"A linen cord"},"es":{"text":"El de lino"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-medium-027","type":"choice","level":"medium","testament":"ot","book":"ECC","chapter":1,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo Eclesiastes 1:2, o que diz o Pregador de todas as coisas?","bible_ref":"Eclesiastes 1:2","verse_text":"Futilidade das futilidades! - diz o Pregador - futilidade das futilidades! Tudo é fútil!"},"fr":{"prompt":"Selon l’Ecclésiaste 1:2, que dit l’Ecclésiaste de toutes choses ?","bible_ref":"Ecclésiaste 1:2","verse_text":"Vanité des vanités, dit l’Ecclésiaste, vanité des vanités, tout est vanité."},"en":{"prompt":"According to Ecclesiastes 1:2, what does the Preacher say about all things?","bible_ref":"Ecclesiastes 1:2","verse_text":"Vanity of vanities, saith the Preacher, vanity of vanities; all is vanity."},"es":{"prompt":"Según Eclesiastés 1:2, ¿qué dice el Predicador de todas las cosas?","bible_ref":"Eclesiastés 1:2","verse_text":"Vanidad de vanidades, dijo el Predicador; vanidad de vanidades, todo vanidad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Tudo é fútil"},"fr":{"text":"Tout est vanité"},"en":{"text":"All is vanity"},"es":{"text":"Todo es vanidad"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Tudo é bom"},"fr":{"text":"Tout est bon"},"en":{"text":"All is good"},"es":{"text":"Todo es bueno"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tudo é novo"},"fr":{"text":"Tout est nouveau"},"en":{"text":"All is new"},"es":{"text":"Todo es nuevo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tudo é eterno"},"fr":{"text":"Tout est éternel"},"en":{"text":"All is eternal"},"es":{"text":"Todo es eterno"}}}]}$json$::jsonb);
