select public.upsert_bank_question($json${"id":"poet2-hard-008","type":"choice","level":"hard","testament":"ot","book":"JOB","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Jó 1:3, quantos camelos tinha Jó antes das suas provações?","bible_ref":"Jó 1:3","verse_text":"E seu patrimônio era sete mil ovelhas, três mil camelos, quinhentas juntas de bois, e quinhentas jumentas; ele também tinha muitíssimos servos, de maneira que este homem era o maior de todos do oriente."},"fr":{"prompt":"Selon Job 1:3, combien de chameaux Job possédait-il avant ses épreuves ?","bible_ref":"Job 1:3","verse_text":"Il possédait sept mille brebis, trois mille chameaux, cinq cents paires de bœufs, cinq cents ânesses, et un très grand nombre de serviteurs. Et cet homme était le plus considérable de tous les fils de l’Orient."},"en":{"prompt":"According to Job 1:3, how many camels did Job have before his trials?","bible_ref":"Job 1:3","verse_text":"His substance also was seven thousand sheep, and three thousand camels, and five hundred yoke of oxen, and five hundred she asses, and a very great household; so that this man was the greatest of all the men of the east."},"es":{"prompt":"Según Job 1:3, ¿cuántos camellos tenía Job antes de sus pruebas?","bible_ref":"Job 1:3","verse_text":"Y su hacienda era siete mil ovejas, y tres mil camellos, y quinientas yuntas de bueyes, y quinientas asnas, y muchísimos criados: y era aquel varón grande más que todos los Orientales."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Três mil"},"fr":{"text":"Trois mille"},"en":{"text":"Three thousand"},"es":{"text":"Tres mil"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sete mil"},"fr":{"text":"Sept mille"},"en":{"text":"Seven thousand"},"es":{"text":"Siete mil"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Seis mil"},"fr":{"text":"Six mille"},"en":{"text":"Six thousand"},"es":{"text":"Seis mil"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Quinhentos"},"fr":{"text":"Cinq cents"},"en":{"text":"Five hundred"},"es":{"text":"Quinientos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-hard-009","type":"choice","level":"hard","testament":"ot","book":"JOB","chapter":42,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Segundo Jó 42:14, como se chamava a primeira das filhas que Jó teve depois da provação?","bible_ref":"Jó 42:14","verse_text":"E chamou o nome da uma Jemima, e o nome da segunda Quézia, e o nome da terceira Quéren-Hapuque."},"fr":{"prompt":"Selon Job 42:14, comment s’appelait la première des filles que Job eut après l’épreuve ?","bible_ref":"Job 42:14","verse_text":"il donna à la première le nom de Jemima, à la seconde celui de Ketsia, et à la troisième celui de Kéren-Happuc."},"en":{"prompt":"According to Job 42:14, what was the name of the first of the daughters Job had after his trial?","bible_ref":"Job 42:14","verse_text":"And he called the name of the first, Jemima; and the name of the second, Kezia; and the name of the third, Keren-happuch."},"es":{"prompt":"Según Job 42:14, ¿cómo se llamaba la primera de las hijas que Job tuvo después de la prueba?","bible_ref":"Job 42:14","verse_text":"Y llamó el nombre de la una, Jemimah, y el nombre de la segunda, Cesiah, y el nombre de la tercera, Keren-happuch."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jemima"},"fr":{"text":"Jemima"},"en":{"text":"Jemima"},"es":{"text":"Jemimah"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Quézia"},"fr":{"text":"Ketsia"},"en":{"text":"Kezia"},"es":{"text":"Cesiah"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quéren-Hapuque"},"fr":{"text":"Kéren-Happuc"},"en":{"text":"Keren-happuch"},"es":{"text":"Keren-happuch"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Diná"},"fr":{"text":"Dina"},"en":{"text":"Dinah"},"es":{"text":"Dina"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-hard-010","type":"choice","level":"hard","testament":"ot","book":"JOB","chapter":42,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Segundo Jó 42:16, quantos anos viveu Jó depois disto?","bible_ref":"Jó 42:16","verse_text":"E depois disto Jó viveu cento e quarenta anos; e viu seus filhos, e os filhos de seus filhos, até quatro gerações."},"fr":{"prompt":"Selon Job 42:16, combien d’années Job vécut-il après cela ?","bible_ref":"Job 42:16","verse_text":"Job vécut après cela cent quarante ans, et il vit ses fils et les fils de ses fils jusqu’à la quatrième génération."},"en":{"prompt":"According to Job 42:16, how many years did Job live after this?","bible_ref":"Job 42:16","verse_text":"After this lived Job an hundred and forty years, and saw his sons, and his sons’ sons, even four generations."},"es":{"prompt":"Según Job 42:16, ¿cuántos años vivió Job después de esto?","bible_ref":"Job 42:16","verse_text":"Y después de esto vivió Job ciento y cuarenta años, y vió á sus hijos, y á los hijos de sus hijos, hasta la cuarta generación."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cento e quarenta"},"fr":{"text":"Cent quarante"},"en":{"text":"A hundred and forty"},"es":{"text":"Ciento cuarenta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Setenta"},"fr":{"text":"Soixante-dix"},"en":{"text":"Seventy"},"es":{"text":"Setenta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cento e vinte"},"fr":{"text":"Cent vingt"},"en":{"text":"A hundred and twenty"},"es":{"text":"Ciento veinte"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Novecentos"},"fr":{"text":"Neuf cents"},"en":{"text":"Nine hundred"},"es":{"text":"Novecientos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-hard-011","type":"choice","level":"hard","testament":"ot","book":"JOB","chapter":38,"verse_start":6,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Jó 38:6-7, quem cantava alegremente quando Deus pôs a pedra angular da terra?","bible_ref":"Jó 38:6-7","verse_text":"Sobre o que estão fundadas suas bases? Ou quem pôs sua pedra angular, Quando as estrelas do amanhecer cantavam alegremente juntas, e todos os filhos de Deus jubilavam?"},"fr":{"prompt":"Selon Job 38:6-7, qui éclatait en chants d’allégresse quand Dieu posa la pierre angulaire de la terre ?","bible_ref":"Job 38:6-7","verse_text":"Sur quoi ses bases sont-elles appuyées? Ou qui en a posé la pierre angulaire, Alors que les étoiles du matin éclataient en chants d’allégresse, Et que tous les fils de Dieu poussaient des cris de joie?"},"en":{"prompt":"According to Job 38:6-7, who sang together when God laid the corner stone of the earth?","bible_ref":"Job 38:6-7","verse_text":"Whereupon are the foundations thereof fastened? or who laid the corner stone thereof; When the morning stars sang together, and all the sons of God shouted for joy?"},"es":{"prompt":"Según Job 38:6-7, ¿quiénes alababan cuando Dios puso la piedra angular de la tierra?","bible_ref":"Job 38:6-7","verse_text":"¿Sobre qué están fundadas sus basas? ¿ó quién puso su piedra angular, Cuando las estrellas todas del alba alababan, y se regocijaban todos los hijos de Dios?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"As estrelas da manhã"},"fr":{"text":"Les étoiles du matin"},"en":{"text":"The morning stars"},"es":{"text":"Las estrellas del alba"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os reis da terra"},"fr":{"text":"Les rois de la terre"},"en":{"text":"The kings of the earth"},"es":{"text":"Los reyes de la tierra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As aves do céu"},"fr":{"text":"Les oiseaux du ciel"},"en":{"text":"The birds of the ai