select public.upsert_bank_question($json${"id":"poet2-hard-012","type":"choice","level":"hard","testament":"ot","book":"PSA","chapter":90,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo o Salmo 90:10, a quantos anos chegam os dias da nossa vida?","bible_ref":"Salmos 90:10","verse_text":"Os dias de nossa vida chegam até os setenta anos; e os que são mais fortes, até os oitenta anos; e o melhor deles é canseira e opressão, porque logo é cortado, e saímos voando."},"fr":{"prompt":"Selon le Psaume 90:10, à combien d’années s’élèvent les jours de nos années ?","bible_ref":"Psaumes 90:10","verse_text":"Les jours de nos années s’élèvent à soixante-dix ans, Et, pour les plus robustes, à quatre-vingts ans; Et l’orgueil qu’ils en tirent n’est que peine et misère, Car il passe vite, et nous nous envolons."},"en":{"prompt":"According to Psalm 90:10, how long are the days of our years?","bible_ref":"Psalms 90:10","verse_text":"The days of our years are threescore years and ten; and if by reason of strength they be fourscore years, yet is their strength labour and sorrow; for it is soon cut off, and we fly away."},"es":{"prompt":"Según el Salmo 90:10, ¿cuántos años son los días de nuestra edad?","bible_ref":"Salmos 90:10","verse_text":"Los días de nuestra edad son setenta años; que si en los más robustos son ochenta años, con todo su fortaleza es molestia y trabajo; porque es cortado presto, y volamos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Setenta anos"},"fr":{"text":"Soixante-dix ans"},"en":{"text":"Threescore years and ten"},"es":{"text":"Setenta años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cem anos"},"fr":{"text":"Cent ans"},"en":{"text":"A hundred years"},"es":{"text":"Cien años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cento e vinte anos"},"fr":{"text":"Cent vingt ans"},"en":{"text":"A hundred and twenty years"},"es":{"text":"Ciento veinte años"}}},{"position":4,"is_correct":false,"texts":{