select public.upsert_bank_question($json${"id":"poet2-hard-013","type":"choice","level":"hard","testament":"ot","book":"PSA","chapter":127,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Que nome aparece no título do Salmo 127, um cântico dos degraus?","bible_ref":"Salmos 127:1","verse_text":"Cântico dos degraus, de Salomão: Se o SENHOR não estiver edificando a casa, em vão trabalham nela seus construtores; se o SENHOR não estiver guardando a cidade, em vão o guarda vigia."},"fr":{"prompt":"Quel nom figure dans le titre du Psaume 127, un cantique des degrés ?","bible_ref":"Psaumes 127:1","verse_text":"Cantique des degrés. De Salomon. Si l’Éternel ne bâtit la maison, Ceux qui la bâtissent travaillent en vain; Si l’Éternel ne garde la ville, Celui qui la garde veille en vain."},"en":{"prompt":"Which name appears in the title of Psalm 127, a Song of degrees?","bible_ref":"Psalms 127:1","verse_text":"A Song of degrees for Solomon. Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain."},"es":{"prompt":"¿Qué nombre aparece en el título del Salmo 127, un cántico gradual?","bible_ref":"Salmos 127:1","verse_text":"Cántico gradual: para Salomón. SI Jehová no edificare la casa, en vano trabajan los que la edifican: si Jehová no guardare la ciudad, en vano vela la guarda."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Salomão"},"fr":{"text":"Salomon"},"en":{"text":"Solomon"},"es":{"text":"Salomón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"David"},"fr":{"text":"David"},"en":{"text":"David"},"es":{"text":"David"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Asafe"},"fr":{"text":"Asaph"},"en":{"text":"Asaph"},"es":{"text":"Asaph"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"poet2-hard-014","type":"choice","level":"hard","testament":"ot","book":"PSA","chapter":128,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo o Salmo 128:3, os teus filhos serão como plantas de quê, ao redor da tua mesa?","bible_ref":"Salmos 128:3","verse_text":"Tua mulher será como a videira frutífera, ao lado de tua casa; e teus filhos como plantas de oliveira ao redor de tua mesa."},"fr":{"prompt":"Selon le Psaume 128:3, tes fils seront comme des plants de quoi, autour de ta table ?","bible_ref":"Psaumes 128:3","verse_text":"Ta femme est comme une vigne féconde Dans l’intérieur de ta maison; Tes fils sont comme des plants d’olivier, Autour de ta table."},"en":{"prompt":"According to Psalm 128:3, your children shall be like what plants round about your table?","bible_ref":"Psalms 128:3","verse_text":"Thy wife shall be as a fruitful vine by the sides of thine house: thy children like olive plants round about thy table."},"es":{"prompt":"Según el Salmo 128:3, ¿como plantas de qué serán tus hijos alrededor de tu mesa?","bible_ref":"Salmos 128:3","verse_text":"Tu mujer será como parra que lleva fruto á los lados de tu casa; tus hijos como plantas de olivas alrededor de tu mesa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De oliveira"},"fr":{"text":"D’olivier"},"en":{"text":"Olive"},"es":{"text":"De olivas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De videira"},"fr":{"text":"De vigne"},"en":{"text":"Vine"},"es":{"text":"De parra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De figueira"},"fr":{"text":"De figuier"},"en":{"text":"Fig"},"es":{"text":"De higuera"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De cedro"},"fr":{"text":"De cèdre"},"en":{"text":"Cedar"},"es":{"text":"De cedro"}}}]}$json$::jsonb);
