select public.upsert_bank_question($json${"id":"poet2-hard-021","type":"choice","level":"hard","testament":"ot","book":"PRO","chapter":16,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"Segundo Provérbios 16:32, quem é melhor do que o valente?","bible_ref":"Provérbios 16:32","verse_text":"Melhor é o que demora para se irritar do que o valente; e melhor é aquele que domina seu espírito do que aquele que toma uma cidade."},"fr":{"prompt":"Selon Proverbes 16:32, qui vaut mieux qu’un héros ?","bible_ref":"Proverbes 16:32","verse_text":"Celui qui est lent à la colère vaut mieux qu’un héros, Et celui qui est maître de lui-même, que celui qui prend des villes."},"en":{"prompt":"According to Proverbs 16:32, who is better than the mighty?","bible_ref":"Proverbs 16:32","verse_text":"He that is slow to anger is better than the mighty; and he that ruleth his spirit than he that taketh a city."},"es":{"prompt":"Según Proverbios 16:32, ¿quién es mejor que el fuerte?","bible_ref":"Proverbios 16:32","verse_text":"Mejor es el que tarde se aira que el fuerte; y el que se enseñorea de su espíritu, que el que toma una ciudad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O que demora a irritar-se"},"fr":{"text":"Celui qui est lent à la colère"},"en":{"text":"He that is slow to anger"},"es":{"text":"El que tarde se aira"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O que tem muitos cavalos"},"fr":{"text":"Celui qui a beaucoup de chevaux"},"en":{"text":"He that has many horses"},"es":{"text":"El que tiene muchos caballos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O que fala muito"},"fr":{"text":"Celui qui parle beaucoup"},"en":{"text":"He that speaks much"},"es":{"text":"El que habla mucho"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O que ajunta ouro"},"fr":{"text":"Celui qui amasse de l’or"},"en":{"text":"He that gathers gold"},"es":{"text":"El que junta oro"}}}]}$json$::jsonb);
