select public.upsert_bank_question($json${"id":"poet2-hard-035","type":"verse","level":"hard","testament":"ot","book":"ECC","chapter":9,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Tudo quanto vier à tua mão para fazer, faze conforme as tuas _____; porque no Xeol, para onde vais, não há trabalho, nem planos, nem conhecimento, nem sabedoria alguma.","bible_ref":"Eclesiastes 9:10","verse_text":"Tudo quanto vier à tua mão para fazer, faze conforme as tuas forças; porque no Xeol, para onde vais, não há trabalho, nem planos, nem conhecimento, nem sabedoria alguma."},"fr":{"prompt":"Tout ce que ta main trouve à faire avec ta _____, fais-le; car il n’y a ni œuvre, ni pensée, ni science, ni sagesse, dans le séjour des morts, où tu vas.","bible_ref":"Ecclésiaste 9:10","verse_text":"Tout ce que ta main trouve à faire avec ta force, fais-le; car il n’y a ni œuvre, ni pensée, ni science, ni sagesse, dans le séjour des morts, où tu vas."},"en":{"prompt":"Whatsoever thy hand findeth to do, do it with thy _____; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest.","bible_ref":"Ecclesiastes 9:10","verse_text":"Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest."},"es":{"prompt":"Todo lo que te viniere á la mano para hacer, hazlo según tus _____; porque en el sepulcro, adonde tú vas, no hay obra, ni industria, ni ciencia, ni sabiduría.","bible_ref":"Eclesiastés 9:10","verse_text":"Todo lo que te viniere á la mano para hacer, hazlo según tus fuerzas; porque en el sepulcro, adonde tú vas, no hay obra, ni industria, ni ciencia, ni sabiduría."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"alegrias"},"fr":{"text":"joie"},"en":{"text":"joy"},"es":{"text":"alegrías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"riquezas"},"fr":{"text":"richesse"},"en":{"text":"riches"},"es":{"text":"riquezas"}}},{"posi